#!/usr/bin/env node
// Tauri ACL 4-source cross-check audit — KL-040.
// 사고 패턴: KL-035 life_screen_capture rename 사고 (release 3회 헛수고).
// 호출처: `node scripts/tauri-acl-audit.mjs` / `npm run verify` (verify.mjs step 4).
//
// 검증 4 source:
//   backend   — #[tauri::command] fn names in src-tauri/src/**/*.rs
//   handler   — generate_handler![...] in src-tauri/src/lib.rs
//   perms     — commands.allow in src-tauri/permissions/**/*.toml (incl. autogenerated)
//   caps      — permission identifiers in src-tauri/capabilities/default.json
//
// 5 cross-checks (모두 0 이어야 통과):
//   backend ∖ handler  → 구현만 있고 handler 미등록 (dead fn)
//   handler ∖ backend  → handler 에 등록됐지만 구현 없음 (compile fail)
//   backend ∖ perms    → 구현/handler 있지만 permission 정의 없음 (KL-035 본 사고)
//   perms   ∖ backend  → permission 에 옛 이름 잔재 (stale ACL)
//   perm_ids ∖ caps    → permission 정의 있지만 capabilities 미등록 (사문화 permission)
//
// Note: caps → perm_ids 역방향 (caps 에 있지만 perm 없음) 은 core:* / updater:* 같은
//   외부 플러그인 ID 가 많아 false-positive 폭발 → audit 제외.

import { readdirSync, readFileSync, existsSync } from 'node:fs';
import { join, resolve } from 'node:path';

const ROOT = resolve(import.meta.dirname, '../apps/karmolab-tauri/src-tauri');

// --- 1. backend commands ---
function parseBackendCommands() {
  const cmds = new Set();
  const srcDir = join(ROOT, 'src');
  function walkDir(dir) {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) { walkDir(full); continue; }
      if (!entry.name.endsWith('.rs')) continue;
      const src = readFileSync(full, 'utf8');
      const lines = src.split('\n');
      for (let i = 0; i < lines.length; i++) {
        if (lines[i].trim() === '#[tauri::command]') {
          for (let j = i + 1; j < Math.min(i + 4, lines.length); j++) {
            const m = lines[j].match(/(?:pub\s+)?(?:async\s+)?fn\s+([a-zA-Z_][a-zA-Z0-9_]*)/);
            if (m) { cmds.add(m[1]); break; }
          }
        }
      }
    }
  }
  walkDir(srcDir);
  return cmds;
}

// --- 2. handler commands ---
function parseHandlerCommands() {
  const cmds = new Set();
  const libPath = join(ROOT, 'src', 'lib.rs');
  if (!existsSync(libPath)) return cmds;
  const src = readFileSync(libPath, 'utf8');
  const m = src.match(/generate_handler!\[([\s\S]*?)\]/);
  if (!m) return cmds;
  for (const token of m[1].split(/[\s,\n]+/)) {
    const clean = token.trim();
    if (clean && !clean.startsWith('//')) cmds.add(clean);
  }
  return cmds;
}

// --- 3. permission commands + permission identifiers ---
function parsePermissions() {
  const permCmds = new Set();
  const permIds = new Set();
  function readTomlDir(dir) {
    if (!existsSync(dir)) return;
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) { readTomlDir(full); continue; }
      if (!entry.name.endsWith('.toml')) continue;
      const src = readFileSync(full, 'utf8');
      // identifier lines
      for (const m of src.matchAll(/identifier\s*=\s*"([^"]+)"/g)) permIds.add(m[1]);
      // commands.allow arrays
      for (const m of src.matchAll(/commands\.allow\s*=\s*\[([\s\S]*?)\]/g)) {
        for (const item of m[1].matchAll(/"([^"]+)"/g)) permCmds.add(item[1]);
      }
    }
  }
  readTomlDir(join(ROOT, 'permissions'));
  return { permCmds, permIds };
}

// --- 4. capability permission identifiers ---
function parseCapsPermIds() {
  const ids = new Set();
  const capDir = join(ROOT, 'capabilities');
  if (!existsSync(capDir)) return ids;
  for (const entry of readdirSync(capDir, { withFileTypes: true })) {
    if (!entry.name.endsWith('.json')) continue;
    const full = join(capDir, entry.name);
    try {
      const json = JSON.parse(readFileSync(full, 'utf8'));
      for (const perm of (json.permissions ?? [])) {
        if (typeof perm === 'string') ids.add(perm);
      }
    } catch { /* skip malformed */ }
  }
  return ids;
}

// --- diff helper ---
function diff(a, b) {
  return [...a].filter(x => !b.has(x)).sort();
}

// --- main ---
const backend  = parseBackendCommands();
const handler  = parseHandlerCommands();
const { permCmds, permIds } = parsePermissions();
const capsIds  = parseCapsPermIds();

const checks = [
  { label: 'backend ∖ handler  (dead fn — in src but not in generate_handler)',    items: diff(backend, handler)  },
  { label: 'handler ∖ backend  (missing impl — in handler but not #[tauri::command])', items: diff(handler, backend)  },
  { label: 'backend ∖ perms    (no permission defined — KL-035 사고 패턴)',         items: diff(backend, permCmds) },
  { label: 'perms   ∖ backend  (stale ACL — old name in permission file)',          items: diff(permCmds, backend) },
  { label: 'perm_ids ∖ caps    (permission defined but not in capabilities)',
    items: diff(new Set([...permIds].filter(id => !id.startsWith('deny-'))), capsIds) },
];

let failed = false;
for (const { label, items } of checks) {
  if (items.length === 0) {
    console.log(`[acl-audit] OK  ${label}`);
  } else {
    console.error(`[acl-audit] X  ${label}`);
    for (const item of items) console.error(`             - ${item}`);
    failed = true;
  }
}

if (failed) {
  console.error('\n[acl-audit] FAIL — ACL mismatch detected. Fix before push.');
  process.exit(1);
} else {
  console.log('\n[acl-audit] OK — ACL 4-source 정합 확인');
}
